  "summary": "اختصاص محاكم الجمهورية بنظر الدعاوى التى ترفع على المصرى ولو لم يكن له موطن أو محل إقامة\nفى الجمهورية .م ٢٨مرافعات .مؤداه .اختصاصها بنظر دعوى الأجنبى بطلب إلزام المصرى بالوفاء\nبالتزامه الناشئ بالخارج .عدم جواز احتجاج الأخير بعدم إقامته بمصر أو انطباق القانون الأجنبى .علة\nذلك .انبساط ولاية المحاكم المصرية على المصرى أينما كان وعلى جميع المنازعات التى يكون طرفاً\nفيها .الاستثناء .الدعاوى العقارية المتعلقة بعقار واقع فى الخارج شخصية أم عينية أو مختلطة .",
  "rule": "النصفى الم ادة ٢٨م نقانون المرافعات على أن \" تختص محاكم الجمهورية بنظر\nالدعاوى التى ترفع على المصرى ولو لم يكن له موطن أو محل إقامة فى الجمهورية وذلك\nفيما عدا الدعاوى العقارية المتعلقة بعقار واقع فى الخارج \" يدل على أن محاكم الجمهورية\nتختص بنظر الدعاوى التى ترفع على المصرى ،حتى ولو لم يكن له موطن أو محل إقامة\nفى الجمهورية ،وعلى ذلك فالمصرى الذى يقيم فى الخارج ويتعامل مع شخص أجنبى لا\nيمك نأن يتف ادى اختصاص المح اكم المص رية إذا قام ذلك الأجنب ى برفع دعواه أمامها\nلمطالبة المصرى بوفاء التزامه ولا يجوز للمصرى فى هذه الحالة أن يحتج بأن العلاقة نشأت\nفى الخارج ،أو بأنه لا يقيم فى مصر أو أن القانون الأجنبى هو الواجب التطبيق إذ تنبسط\nولاية المحاكم المصرية على المصرى أينما كان وعلى جميع المنازعات التى يكون طرفاً فيها\nأيا كانت هذه المنازعات ويستثنى من ذلك الدعاوى العقارية المتعلقة بعقار واقع فى الخارج\nفهذه الدعاوى لا يختص بها القضاء المصرى سواء أكانت الدعوى شخصية عقارية أم عينية\nعقارية أو مختلطة .\n\" اختصاص المحاكم المصرية بنظر الدعاوى غير المتعلقة بعقار يقع بالخارج التى\nترفع على مصرى متجنس بجنسية أجنبية \"",
