  "summary": "انعقاد الاختصاص للمحاكم المصرية فى الدعاوى التى ترفع على الأجنبى الذى ليس له محل إقامة فى\nمصر .شرطه .أن تكون الدعوى متعلقة بمال موجود فى مصر أو كانت متعلقة بالتزام نشأ أو نفذ أو\nكان واجباً التنفيذ فيها .م ٣٠مرافعات \" .مثال فى تأمين \" .",
