  "summary": "مبدأ إقليمية إجراءات شهر الإفلاس وما يصدر من أحكام بشأنه .مفهومه فى قانون التجارة الملغى\nالصادر سنة ١٨٨٣والمادتين ٢/٧٠٠ ، ٢/٥٥٩ق التجارة رقم ١٧لسنة .١٩٩٩أن هذه الإج راءات\nوتلك الأحكام لا تسرى ولا تنتج آثارها إلا فى إقليم الدولة التى صدرت فيها .مؤداه .عدم امتدادها إلى\nالدول الأخرى التى يكون للمفلس أموال ودائنون فيها .الاستثناء .أن تكون هناك اتفاقيات دولية ثنائية أو\nمتعددة الأط راف نافذة فى مصر تقضى بغير ذلك .أث ره .اختصاص القضاء المصرى بشهر إفلاس\nالشركة الأجنبية التى لها فى مصر فرع أو كالة .",
  "rule": "المستقر فى أحكام القضاء والاتجاه الغال بمن آراء الفقهاء فى ظل سريان أحكام قانون\nالتجارة الملغى الصادر سنة ١٨٨٣الذى سرت أحكامه على إجراءات رفع الدعوى المبتدأة\nوأخذ به قضاء هذه المحكمة من وجوب الأخذ بمبدأ اقليمية إجراءات شهر الإفلاس وما\nيصدر من أحكام بشأنها ،والذى يعنى أن هذه الإجراءات وتلك الأحكام التى تصدر نفاذاً\nلها لا تسرى ولا تنتج آثارها إلا فى إقليم الدولة التى صدرت فيها دون أن تمتد إلى الدول\nالأخرى التى يكون للمدين المفلس أموال أو دائنون فيها ما لم تبرم اتفاقيات دولية ثنائية أو\nمتعددة الأطراف نافذة فى مصر تقضى بغير ذلك ،وتفريعاً على هذا المبدأ فقد تبنى المشرع\nفى قانون التجارة الحالى رقم ١٧لسنة ١٩٩٩المعمول به اعتبا اًر من الأول من أكتوبر سنة\n١٩٩٩أثناء نظر الاستئناف المقام على الحكم الصادر فى الدعوى المبتدأة – اختصاص\nالقضاء المصرى بشهر إفلاس التاجر أو الشركة الأجنبية فى مصر إذا كان لها فيها فرع\nأو وكالة على أن يقتصر أثر حكم شهر الإفلاس على أى منهما وعلى أموال كل منهما\nالموج ودة ف ى مصر دون أن يمتد إلى محل الت اجر الرئيس ى أو مركز الش ركة الرئيس ى\nوأموالهما خارج مصر ،وذلك إعمالاً لما قضت به الفقرة الثانية من المادتين ٧٠٠ ، ٥٥٩\nمن هذا القانون .",
