  "summary": "وقوع مركز إدارة الش ركة المس تأنف ضدها ونش اطها الرئيس ى ف ى دولة أجنبية .لا يستتبع أن يمتد\nالاختصاص بشهر إفلاسها للمحاكم المصرية لمجرد وجود فرع لها داخل مصر قُضى بشهر إفلاسه .\nانتهاء الحكم المستأنف إلى هذه النتيجة .صحيح .",
  "rule": "إذ كان الواقع حسبما حصله الحكم المس تأنف وسائر الأوراق أن دعوى إفلاس الش ركة\nالمستأنف ضدها قد أقيمت على سند من توقف مكتب التمثيل التابع لها فى مصر عن سداد\nالمبلغ المس تحق للمستأنفة لا ذى قضى به الحكم الص ادر فى الاس تئناف رقم .....لس نة\n١١١ق القاهرة بما ينبىء عن اضطراب مركزه المالى ،والذى أوضحت أسبابه المرتبطة\nبمنطوق قضائه استناداً إلى أحكام المادتين ١٦٥من القانون رقم ١٥٩لسنة ١٩٨١بشأن\nشركات المساهمة ،والمادة ١٣من قرار وزير الصحة بتنظيم المكاتب العلمية نفاذاً لأحكام\nالق انون رقم ١٢٧لس نة ، ١٩٥٥وم اثبت من أوراق الدعوى والمس تندات المقدمة فيها\nومحاضر أعمال الخبرة أن المكتب العلمى للشركة المستأنف ضدها فى مصر شركة مصرية\nتتمتع بشخصية اعتبارية مستقلة عنها ،وأن هذا المكتب يعد فرعاً لها بمصر وقضى بإلزامها\nبالمبلغ الذى أقيمت به دعوى الإفلاس ،بما كان يتعين أن يقتصر نطاق اختصاص المحاكم\nالمص رية بنظ ردع وى شهر الإف لاس على الفرع الك ائن بمصر وال ذى يتمتع بشخصية\nاعتبارية مستقلة أخذاً بحجية ذلك الحكم الذى صدر بين ذات الخصوم وكان ما قضى به\nأساس اً لهذه الدعوى دون أن يمتده ذا الاختصاص إلى شهر إفلاس الش ركة الأجنبية\nالمستأنف عليها التى يقع مركز إدارتها ونشاطها الرئيسى فى دولة أجنبية ،وكان الحكم\nالمستأنف لم يخالف فى قضائه هذا النظر فإنه يتعين تأييده .\n\" اختصاص المحاكم المصرية بالمنازعات المتعلقة بنقل البضائع بح ارً من الخارج إلى",
