  "summary": "تطبيق ق ٢٧لسنة . ١٩٩٤مقصور على التحكيم الذى يجرى فى مصر .مؤداه .عدم سريانه\nعلى التحكيم الذى يجرى خارجها .شرطه .م ١من القانون آنف البيان .مقتضاه .عدم اختصاص\nالمحاكم المصرية بدعوى بطلان حكم تحكيم غير الخاضع لقانون التحكيم المصرى .",
  "rule": "النص فى المادة ) (١من القانون رقم ٢٧لسنة ١٩٩٤فى شأن التحكيم فى المواد المدنية\nوالتجارية على أن \" مع عدم الإخلال بأحكام الاتفاقيات الدولية المعمول بها فى جمهورية\nمصر العربية تسرى أحكام هذا القانون على كل تحكيم بين أطراف من أشخاص القانون\nالعام أو القانون الخاص أياً كانت طبيعة العلاقة القانونية التى يدور حولها النزاع ،إذا كان\nهذا التحكيم يجرى فى مصر أو كان تحكيم اً تجاري اً يجرى فى الخارج واتفق أط ارفه على\nإخضاعه لأحكام هذا القانون ، \" ..يدل على أن المشرع قصر تطبيق أحكام هذا القانون\nعلى التحكيم الذى يجرى فى مصر ،وعدم سريانه على كل تحكيم يجرى فى خارج البلاد\nإلا إذا كان تحكيم اً تجاري اً دولي اً اتفق أط ارفه على اخضاعه لتلك الأحكام ،وعلى ذلك إذا\nصدر حكم تحكيم أجنبى غير خاضع لأحكام قانون التحكيم المصرى بأن صدر فى الخارج\nولم يتفق الطرفان على خضوعه للقانون المصرى وفقاً للمادة ) (١آنفة الذكر فإن المحاكم\nالمصرية تكون غير مختصة بدعوى بطلانه .",
