  "summary": "الاختصاص القيم ى للمح اكم .تعلق ه بالنظام العام .م ١٠٩مرافع ات .عل ة ذلك .اس تهدافه تحقيق\nمصلحة عامة لا مصلحة خاصة بالمتقاضين .",
  "rule": "إن قواعد الاختصاص القيم ى للمح اكم تتعلق بالنظام العام طبق اً للم ادة ١٠٩م نقانون\nالمرافعات لأنها تستهدف تحقيق مصلحة عامة هى حسن تنظيم القضاء لا مصلحة خاصة\nبالمتقاضين .",
