  "summary": "سرية المداولة .ما تعنيه .",
  "rule": "إن سرية المداولة تعنى ألا يشترك فيها غير قضاة الهيئة التى نظرت الدعوى ،فضلاً عن\nضرورة حصولها س اًر بينهم دون سماعها من جانب غيرهم .",
