  "summary": "إيراد صفة أمين السر أمام اسم وكيل النيابة بديباجة الحكم نتيجة خطأ مادى .لا بطلان .",
  "rule": "إذ كان الثابت من مطالعة كافة محاضر الجلسات أمام محكمة أول درجة تمثيل النيابة فيها\nبما فى ذلك تاريخ جلسة النطق بالحكم بحضور الأستاذ ........وكيل النيابة ،ولا ينال من\nذلك ورود خطأ مادى بديباجة الحكم عند إعداده بإيراد صفة أمين السر أمام اسم وكيل\nالنيابة الثابت بمحضر الجلسة بما يترتب عليه أن يكون النعى ببطلان الحكم على غير\nأساس .",
