  "subcategory": "حكم",
  "summary": "عدم طعن بعض المطعون عليهم على القضاء برفض استئنافهم .أث ره .صيرورته بات اً بالنسبة لهم .\nمؤداه .عدم قبول اختصامهم فى الطعن بالنقض على حكم فى ذات النزاع لاحق لذلك القضاء .",
  "rule": "إذ كان الثاب تب الأوراق أن المطع ونض دهما )ثاني اً( ٕوان كانا ضمن الخصوم ف ى الحكم\nالأول الصادر من محكمة الاستئناف بتاريخ ١٩من فبراير سنة ٢٠٠٢لإقامتهما الاستئناف\nرقم ....لسنة ...ق القاهرة إلا أنه وقد قضت المحكمة برفضه ولم يطعنا عليه بطريق\nالنقض أسوة بما سلكته الطاعنة والمطعون ضدها أولاً فإن هذا القضاء يكون قد أضحى باتاً\nومن ثم لا يكونان طرفاً فى خصومة الحكم المطعون فيه اللاحق عليه – محل هذا الطعن\n– بما يتعين معه القضاء بعدم قبول اختصامهما فى الطعن .",
