  "subcategory": "حكم",
  "summary": "قضاء الحكم المطعون فيه بإلغاء الحكم المستأنف القاضى بعدم قبول الدعوى وبقبولها وبإعادتها إلى\nمحكمة أول درجة .غير منهى للخصومة .أثره .عدم جواز الطعن فيه بالنقض على استقلال .",
  "rule": "إذ كان الحكم المطعون فيه وقد اقتصر فى قضائه على إلغاء الحكم المستأنف فيما قضى به\nمن عدم قبول الدعوى وبقبولها وبإعادة القضية لمحكمة أول درجة للقضاء فى موضوعها\nوهو قضاء غير منه للخصومة كلها ،إذ إنه ليس من الأحكام المستثناة الواردة على سبيل\nالحصر فى المادة ٢١٢من قانون المرافعات ،ومن ثم فإنه لا يجوز الطعن فيه بالنقض\nعلى استقلال .",
