  "rule": "إذ كان الحكم المستأنف قد قضى ببطلان إخطار الطاعن بالنموذج ١٨ضرائب ٥ ،ضريبة\nعامة وبإعادة الأوراق للمأمورية لإعادة الربط والإخطار وهو حكم لا تنتهى به الخصومة\nوليس من بين الأحكام الت ى يجوز استئنافها اس تقلالاً عم لاً بالم ادة آنفة البي ان\n) ٢١٢مرافعات ( ،ومن ثم فإنه يتعين القضاء بعدم جواز الاستئناف .",
