  "summary": "سلامة الحكم .ش رطه .إي راد الدفوع الش كلية والموض وعية والرد عليها أياً كان حظها من الص واب\nأو الخطأ .إغفال ذلك .أثره .البطلان .م ١٧٨ق المرافعات .",
  "rule": "المقرر أنه يتعين لسلامة الحك مأن يورد ف ى أسبابه الدفوع الش كلية وغيرها من الدفوع\nالموضوعية الأخرى والرد عليها أياً كان حظها من الصواب أو الخطأ ٕوالا كان ذلك مشوباً\nبالبطلان وذلك على هدى مما تقضى به المادة ١٧٨من قانون المرافعات .",
