  "summary": "توافر الصفة فى تمثيل الشخص الاعتبارى الخاص أو العام .مناطها .حقيقة الواقع .أثره .",
  "rule": "العبرة فى مدى توافر الصفة فى تمثيل الشخص الاعتبارى الخاص أو العام هو بحقيقة الواقع\nبغض النظر عن الوصف الذى يخلعه على نفسه .",
