  "summary": "اعتبار الشخص طرف اً فى خصومة بتمثيل الغير له .شرطه .أن يكون التمثيل مقطوع اً به اتفاق اً أو\nقانوناً.",
  "rule": "أن الشخص لا يعد طرفاً فى خصومة بتمثيل الغير له إلا إذا كان هذا التمثيل مقطوعاً به\nاتفاقاً أو قانوناً .",
