  "summary": "الدفع الشكلى .غايته .النيل من صحة الخصومة والإجراءات المكونة لها .",
  "rule": "المقرر أنه يقصد بال دفوع الش كلية كل دفع يتعل قب الإجراءات دون أن تواجه موضوع\nالخص ومة ف ى الدعوى أو الحق الم دعى به ٕوانم ا تستهدف الني لم نصحة الخص ومة\nوالإجراءات المكونة لها .",
