  "summary": "انقضاء الدعوى الجنائية بمضى المدة أو بوفاة المتهم .تعلقه بالنظام العام ٠التزام المحكمة بإعماله من\nتلقاء نفسها .جواز إثارته لأول مرة أمام محكمة النقض .شرطه .",
  "rule": "إن انقضاء الدعوى الجنائية بمضى المدة أو بوفاة المتهم متعلق اً بالنظام العام يتعين على\nالمحكمة إعماله من تلقاء نفسها ويجوز إثارته لأول مرة أمام محكمة النقض مادامت أوراق\nالدعوى ومستنداتها ترشح له .",
