  "summary": "خلو أسباب الطعن الضريبى من نعى قانونى .أثره .ليس للنيابة العامة أن تطلب إلى محكمة النقض\nالقضاء بانقضاء الخصومة فيه .علة ذلك .",
  "rule": "إن ما انتهت إليه النيابة العامة فى رأيها بانقضاء الخصومة يكون فى غير محله بعد أن\nخلت أسباب الطعن من نعى قانونى يوجب أن تعرض له حتى ينفتح لها الحق فى طلب\nالحكم بانقضاء الخصومة متى تحققت شروطه .",
