  "summary": "األمين العام لصندوق التدريب والتأهيل .صاحب الصفة في تمثيله أمام القضاء .م 5\nمن قرار رئيس مجلس الوزراء رقم 1543لسنة 2003بشأن تشكيل نظام العمل بمجلس إدارة\nذلك الصندوق .",
  "rule": "مفاد نص المادة الخامسة من قرار رئيس مجلس الوزراء رقم 1543لسنة\n2003بشأن تشكيل ونظام العمل بمجلس إدارة صندوق تمويل التدريب والتأهيلْ ،\nبأن\nاألمين العام – المطعون ضده األول -هو من يمثل الصندوق أمام القضاء.",
