  "summary": "صفة الشريك في شركة التضامن .ثبوتها من عقد الشركة .شرطه .استيفاء العقد\nلإلجراءات القانونية .",
  "rule": "الصفة تثبت للشريك في شركة التضامن من واقع عقد الشركة المستوفي\nلإلجراءات التي يتطلبها القانون وأخصها القيد في السجل والشهر.\nاالتفاق على استمرار الشركة بين الشركاء :",
