  "subcategory": "بعض أنواع العقود : عقد البيع المركب :",
  "summary": "العقد المركب .ماهيته .مزيج من عقدين .مثال .تضمن عقد البيع عقد انتفاع أو\nإيجار وقد يتوالى العقدان الواحد بعد اآلخر .",
  "rule": "إن العقد المركب يكون مزيجاً من عقدين كعقد البيع إذا تضمن مع عقد\nالبيع عقد انتفاع أو إيجار وقد يتوالى العقدان الواحد بعد اآلخر.",
