  "summary": "حظر نقل ملكية السفن المصرية ألجنبي بغير إذن من الوزير المختص .مثال .البيع\nبطالنا مطلًقا .للمحكمة ولكل ذي مصلحة التمسك\nً أو الهبة أو الوصية .مؤداه .بطالن العقد\nبه .",
  "rule": "االتفاق على انتهاك الحظر ببيع السفينة المصرية ألجنبي ،بأي صورة من\nصور نقل ملكية السفن بمقابل أو بدون مقابل -كالبيع أو الهبة أو الوصية -أو\nبطالنا\nً بتأجيرها ألجنبي لمدة تزيد على سنتين ،بغير إذن الوزير المختص ،يكون ً\nباطال\nمطلًقا ،وتقضى به المحكمة من تلقاء نفسها ،ويجوز لكل ذي مصلحة التمسك به.",
