  "summary": "الحجز على سفينة ضماناً لدين بحري .حدوده ومداه .م 8من قرار وزير الخارجية\nرقم 145٩لسنة . 1٩55",
  "rule": "المقرر بنص المادة الثامنة من قرار وزير الخارجية رقم 145٩لسنة 1٩55\nأنه \" -1تسري أحكام هذه االتفاقية في جميع الدول المتعاقدة على كل سفينة تحمل\nعلم إحدى الدول المتعاقدة -2 .يجوز توقيع الحجز على أية سفينة تحمل علم دولة\nغير متعاقدة في دولة متعاقدة بسبب أحد الديون المبينة بالمادة األولى أو بسبب أي\nدين آخر يجيز توقيع الحجز وفقا لقانون هذه الدولة.",
