  "summary": "اتساق المقصود بالدين البحري وقواعد الحجز على السفينة والرهن الرسمي لها .م 5٩\nوما بعدها ق التجارة البحرية وقرار وزير الخارجية 145٩لسنة 1٩55بشأن اتفاقية بروكسل\nالصادر نفاذا له ق 135لسنة . 1٩55",
  "rule": "المقصود بالدين البحري وقواعد الحجز على السفينة والتي نظمتها المواد من\n5٩وما بعدها من قانون التجارة البحرية سالف البيان والرهن الرسمي للسفينة من ذات\nالقانون -دون النظر عن كونها تجارية أو غير تجارية لعموم النص الذي جاءت فيه\n-والذي جاء متسًقا إلحكام اتفاقية بروكسل سالفة الذكر .الصادر بشأنها قرار وزير\nالخارجية رقم 145٩لسنة 1٩55المنشور في الوقائع المصرية بالعدد ٩2الصادر\nفي 28نوفمبر لسنة 1٩55وبموجب القانون رقم 135لسنة 1٩55نفا ًذا لها .",
