  "subcategory": "نقابة األطباء :",
  "summary": "عدم جواز الطعن بالنقض على الحكم الصادر من هيئة التأديب االستئنافية للصيادلة\nبتشكيل خاص لخلو نصوص أحكام ق 4٧لسنة ۱۹6٩من جوازه .",
  "rule": "إذ كان الحكم المطعون فيه صاد اًر من هيئة التأديب االستئنافية للصيادلة\nبتشكيل خاص ،ويدخل في عضويتها عضو عن نقابة الصيادلة وعضو عن الصيدلي\nالطاعن ،وكان القانون رقم 4٧لسنة ۱۹6٩بشأن إنشاء نقابة الصيادلة قد خلت\nنصوص أحكامه من تقرير جواز الطعن بالنقض في األحكام الصادرة من هيئة التأديب\nاالستئنافية للصيادلة ،ومن ثم فإن الطعن بالنقض يكون غير جائز.",
